{
  "manifest_version": 3,
  "name": "Fokus Dulu",
  "version": "1.0.0",
  "description": "Pomodoro 25/5 yang menutup situs pengganggu selama sesi fokus.",
  "icons": { "128": "icons/icon128.png" },
  "action": {
    "default_popup": "popup.html",
    "default_title": "Fokus Dulu"
  },
  "background": { "service_worker": "background.js" },
  "options_page": "options.html",
  "permissions": ["alarms", "storage", "notifications", "declarativeNetRequest"],
  "optional_host_permissions": ["*://*/*"],
  "web_accessible_resources": [
    { "resources": ["blocked.html"], "matches": ["<all_urls>"] }
  ],
  "commands": {
    "mulai-berhenti": {
      "suggested_key": { "default": "Alt+Shift+F" },
      "description": "Mulai atau hentikan sesi fokus"
    }
  }
}

// Service worker: satu-satunya pemegang logika sesi.
// Chrome bisa mematikannya kapan saja saat menganggur, jadi semua keadaan
// disimpan di chrome.storage dan waktu ditunggu oleh chrome.alarms, bukan setTimeout.
const MENIT = { fokus: 25, istirahat: 5 };

async function durasiMs(mode) {
  // Khusus uji: chrome.storage.local.set({ debugDetik: 10 }) membuat tiap sesi 10 detik.
  const { debugDetik } = await chrome.storage.local.get("debugDetik");
  return debugDetik ? debugDetik * 1000 : MENIT[mode] * 60_000;
}

async function mulai(mode) {
  const akhir = Date.now() + (await durasiMs(mode));
  await chrome.storage.local.set({ mode, akhir });
  await chrome.alarms.create("sesi", { when: akhir });
  await chrome.alarms.create("badge", { periodInMinutes: 1 });
  await aturBlokir(mode === "fokus");
  await perbaruiBadge();
}

async function berhenti() {
  await chrome.storage.local.remove(["mode", "akhir"]);
  await chrome.alarms.clearAll();
  await aturBlokir(false);
  await chrome.action.setBadgeText({ text: "" });
}

async function aturBlokir(aktif) {
  // Diisi di langkah "Tutup situs pengganggu selama fokus".
}

async function perbaruiBadge() {
  const { mode, akhir } = await chrome.storage.local.get(["mode", "akhir"]);
  if (!mode) return;
  const menit = Math.max(0, Math.ceil((akhir - Date.now()) / 60_000));
  await chrome.action.setBadgeBackgroundColor({ color: mode === "fokus" ? "#3f6212" : "#57534e" });
  await chrome.action.setBadgeText({ text: String(menit) });
}

function beriTahu(judul, pesan) {
  chrome.notifications.create({ type: "basic", iconUrl: "icons/icon128.png", title: judul, message: pesan });
}

chrome.alarms.onAlarm.addListener(async (alarm) => {
  if (alarm.name === "badge") return perbaruiBadge();
  if (alarm.name !== "sesi") return;
  const { mode } = await chrome.storage.local.get("mode");
  if (mode === "fokus") {
    beriTahu("Sesi fokus selesai", "Istirahat 5 menit dulu. Semua situs sudah terbuka lagi.");
    await mulai("istirahat");
  } else {
    beriTahu("Istirahat selesai", "Siap untuk sesi fokus berikutnya?");
    await berhenti();
  }
});

chrome.runtime.onMessage.addListener((pesan, pengirim, balas) => {
  const kerja = pesan.aksi === "mulai" ? mulai("fokus") : berhenti();
  kerja.then(() => balas({ ok: true }));
  return true; // jawaban dikirim nanti, setelah kerja selesai
});

chrome.commands.onCommand.addListener(async (perintah) => {
  if (perintah !== "mulai-berhenti") return;
  const { mode } = await chrome.storage.local.get("mode");
  await (mode ? berhenti() : mulai("fokus"));
});

// Browser dibuka lagi, atau ekstensi dimuat ulang: alarm bisa saja hilang,
// jadi pulihkan dari storage. Sesi yang sudah lewat langsung diakhiri.
async function pulihkan() {
  const { mode, akhir } = await chrome.storage.local.get(["mode", "akhir"]);
  if (!mode || akhir <= Date.now()) return berhenti();
  await chrome.alarms.create("sesi", { when: akhir });
  await chrome.alarms.create("badge", { periodInMinutes: 1 });
  await perbaruiBadge();
}
chrome.runtime.onStartup.addListener(pulihkan);
chrome.runtime.onInstalled.addListener(pulihkan);

// Tempel di console service worker (chrome://extensions > Fokus Dulu > "service worker").
// 1. Percepat: tiap sesi jadi 10 detik.
chrome.storage.local.set({ debugDetik: 10 });

// 2. Lihat keadaan sekarang.
chrome.storage.local.get(null).then(console.log);
chrome.alarms.getAll().then(console.log);
chrome.declarativeNetRequest.getDynamicRules().then(console.log);

// 3. Selesai menguji: kembali ke 25/5 menit.
chrome.storage.local.remove("debugDetik");

const status = document.getElementById("status");
const sisa = document.getElementById("sisa");
const tombol = document.getElementById("tombol");
const TEKS = {
  fokus: "Sedang fokus. Situs pengganggu ditutup.",
  istirahat: "Istirahat. Semua situs terbuka.",
};
let akhir = null;

function format(ms) {
  const detik = Math.max(0, Math.ceil(ms / 1000));
  const mm = String(Math.floor(detik / 60)).padStart(2, "0");
  const ss = String(detik % 60).padStart(2, "0");
  return `${mm}:${ss}`;
}

function detak() {
  sisa.textContent = akhir ? format(akhir - Date.now()) : "25:00";
}

async function tampilkan() {
  const { mode, akhir: a } = await chrome.storage.local.get(["mode", "akhir"]);
  akhir = a ?? null;
  status.textContent = TEKS[mode] ?? "Belum ada sesi.";
  tombol.textContent = mode ? "Berhenti" : "Mulai fokus 25 menit";
  document.body.dataset.mode = mode ?? "diam";
  detak();
}

tombol.addEventListener("click", () => {
  chrome.runtime.sendMessage({ aksi: akhir ? "berhenti" : "mulai" });
});
document.getElementById("atur").addEventListener("click", () => chrome.runtime.openOptionsPage());

// Service worker yang mengubah storage; popup cukup ikut menampilkan.
chrome.storage.onChanged.addListener((ubah, area) => {
  if (area === "local") tampilkan();
});
setInterval(detak, 1000);
tampilkan();

:root {
  --tinta: #1c1917;
  --latar: #fafaf9;
  --hijau: #3f6212;
  --hijau-muda: #ecfccb;
  --abu: #57534e;
  font-family: system-ui, "Segoe UI", Roboto, sans-serif;
  color: var(--tinta);
  background: var(--latar);
}
body { margin: 0; }
main { padding: 1rem 1.25rem; }
h1 { font-size: 1.1rem; margin: 0 0 .5rem; }
.popup { width: 18rem; }
.popup[data-mode="fokus"] { background: var(--hijau-muda); }
.sisa {
  font-size: 3rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  margin: .25rem 0 .75rem;
}
button {
  display: block;
  width: 100%;
  font: inherit;
  font-weight: 700;
  padding: .6rem;
  margin-bottom: .5rem;
  border: 2px solid var(--tinta);
  border-radius: .5rem;
  background: var(--hijau);
  color: #fff;
  cursor: pointer;
}
button.sekunder { background: #fff; color: var(--tinta); }
button:focus-visible, textarea:focus-visible, a:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}
.kecil { font-size: .85rem; color: var(--abu); }
kbd { border: 1px solid var(--abu); border-radius: .25rem; padding: 0 .3rem; }
.halaman { max-width: 36rem; margin: 3rem auto; padding: 0 1rem; }
textarea { width: 100%; box-sizing: border-box; font: inherit; padding: .5rem; }
.halaman button { width: auto; padding: .6rem 1.2rem; }

const kotak = document.getElementById("situs");
const pesan = document.getElementById("pesan");
const SARAN = ["youtube.com", "instagram.com", "tiktok.com", "x.com"];

// "https://www.youtube.com/watch?v=1" -> "youtube.com"; baris yang bukan domain -> ""
function bersihkan(baris) {
  const domain = baris.trim().toLowerCase()
    .replace(/^[a-z]+:\/\//, "")
    .split(/[/?#:]/)[0]
    .replace(/^www\./, "");
  return /^[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/.test(domain) ? domain : "";
}

chrome.storage.sync.get("situs").then(({ situs }) => {
  kotak.value = (situs ?? SARAN).join("\n");
});

document.getElementById("form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const baris = kotak.value.split("\n").filter((b) => b.trim());
  const situs = [...new Set(baris.map(bersihkan).filter(Boolean))];
  // Izin per situs. Harus diminta langsung saat tombol diklik, sebelum await lain.
  if (situs.length > 0) {
    const diizinkan = await chrome.permissions.request({ origins: situs.map((d) => `*://*.${d}/*`) });
    if (!diizinkan) {
      pesan.textContent = "Belum tersimpan: tanpa izin, situs itu tidak bisa dialihkan ke halaman fokus.";
      return;
    }
  }
  await chrome.storage.sync.set({ situs });
  kotak.value = situs.join("\n");
  const dibuang = baris.length - situs.length;
  pesan.textContent = `Tersimpan: ${situs.length} situs.` +
    (dibuang > 0 ? ` ${dibuang} baris dilewati karena bukan domain atau dobel.` : "");
});

const ATURAN_BLOKIR = 1;

async function aturBlokir(aktif) {
  const { situs = [] } = await chrome.storage.sync.get("situs");
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: [ATURAN_BLOKIR],
    addRules: aktif && situs.length > 0 ? [{
      id: ATURAN_BLOKIR,
      priority: 1,
      action: { type: "redirect", redirect: { extensionPath: "/blocked.html" } },
      condition: { requestDomains: situs, resourceTypes: ["main_frame"] },
    }] : [],
  });
}

// Baru dipasang: buka pengaturan supaya pemakai memilih situs dan memberi izin.
chrome.runtime.onInstalled.addListener(({ reason }) => {
  if (reason === "install") chrome.runtime.openOptionsPage();
});

// Daftar diubah di halaman pengaturan saat sesi fokus berjalan: terapkan langsung.
chrome.storage.onChanged.addListener(async (ubah, area) => {
  if (area !== "sync" || !ubah.situs) return;
  const { mode } = await chrome.storage.local.get("mode");
  if (mode === "fokus") await aturBlokir(true);
});

const sisa = document.getElementById("sisa");

async function detak() {
  const { akhir } = await chrome.storage.local.get("akhir");
  const menit = akhir ? Math.max(0, Math.ceil((akhir - Date.now()) / 60_000)) : 0;
  sisa.textContent = `${menit} menit lagi`;
}
setInterval(detak, 5000);
detak();

{
  "name": "fokus-dulu",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node uji/uji-ekstensi.mjs"
  },
  "devDependencies": {
    "playwright": "^1.64.0"
  }
}

// Uji ujung ke ujung: muat ekstensi di Chromium, jalankan satu putaran
// fokus -> istirahat dengan durasi 8 detik, dan periksa pemblokirannya.
//   npm test
import { chromium } from "playwright";
import assert from "node:assert/strict";
import { cp, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

const profil = await mkdtemp(path.join(tmpdir(), "fokus-uji-"));

// Dialog izin situs tidak bisa diklik oleh Playwright. Karena itu uji memakai
// salinan ekstensi yang sudah memegang izin example.com sejak dipasang.
const ekstensi = await mkdtemp(path.join(tmpdir(), "fokus-ekstensi-"));
await cp(path.resolve("ekstensi"), ekstensi, { recursive: true });
const manifest = JSON.parse(await readFile(path.join(ekstensi, "manifest.json"), "utf8"));
manifest.host_permissions = ["*://*.example.com/*"];
await writeFile(path.join(ekstensi, "manifest.json"), JSON.stringify(manifest));
const SITUS = "https://example.com/";

// Chrome dan Edge bermerek tidak lagi menerima --load-extension.
// channel "chromium" memakai Chromium bawaan Playwright, bisa tanpa jendela (headless).
const buka = () => chromium.launchPersistentContext(profil, {
  channel: "chromium",
  args: [`--disable-extensions-except=${ekstensi}`, `--load-extension=${ekstensi}`],
});

let ctx = await buka();
let [sw] = ctx.serviceWorkers();
sw ??= await ctx.waitForEvent("serviceworker");
const id = new URL(sw.url()).host;
console.log("ekstensi termuat:", id);

// 1. Halaman pengaturan: simpan daftar, baris sampah dilewati.
const opsi = await ctx.newPage();
await opsi.goto(`chrome-extension://${id}/options.html`);
await opsi.fill("#situs", "https://www.example.com/halaman\nbukan situs");
await opsi.click("button[type=submit]");
await opsi.getByText("Tersimpan: 1 situs.").waitFor();
assert.equal(await opsi.inputValue("#situs"), "example.com");
console.log("ok  pengaturan menyimpan example.com");

// 2. Popup dibuka sebagai tab biasa. Durasi dipercepat lewat debugDetik.
const popup = await ctx.newPage();
await popup.goto(`chrome-extension://${id}/popup.html`);
await popup.evaluate(() => chrome.storage.local.set({ debugDetik: 8 }));
await popup.getByRole("button", { name: "Mulai fokus 25 menit" }).click();
await popup.getByText("Sedang fokus.").waitFor();
console.log("ok  sesi fokus dimulai dari popup");

// 3. Selama fokus, example.com dialihkan ke halaman "tetap fokus",
//    baik diketik di bar alamat maupun dibuka dari tautan di situs lain.
const BLOKIR = `chrome-extension://${id}/blocked.html`;
const tab = await ctx.newPage();
await tab.goto(SITUS);
assert.equal(tab.url(), BLOKIR);
await tab.goto("https://example.org/");
await tab.evaluate((url) => { location.href = url; }, SITUS);
await tab.waitForURL(BLOKIR, { timeout: 10_000 });
console.log("ok  example.com dialihkan ke blocked.html");

// 4. Matikan service worker, seperti yang Chrome lakukan saat ia menganggur.
//    Alarm harus tetap membangunkannya saat sesi habis.
const si = await ctx.newPage();
await si.goto("chrome://serviceworker-internals/");
await si.getByRole("button", { name: "Stop" }).click();
await si.getByText("Running Status: STOPPED").waitFor();
await si.close();
console.log("..  service worker dihentikan, menunggu alarm");

await popup.getByText("Istirahat.").waitFor({ timeout: 20_000 });
const notif = await popup.evaluate(() => chrome.notifications.getAll());
assert.ok(Object.keys(notif).length >= 1, "notifikasi akhir sesi harus muncul");
console.log("ok  alarm berbunyi, notifikasi dibuat, mode istirahat");

// 5. Saat istirahat, example.com terbuka lagi.
await tab.goto(SITUS);
assert.equal(new URL(tab.url()).host, "example.com");
console.log("ok  example.com terbuka saat istirahat");

await popup.getByText("Belum ada sesi.").waitFor({ timeout: 20_000 });
console.log("ok  istirahat selesai, sesi berhenti");

// 6. Tutup browser, buka lagi dengan profil yang sama: daftar situs masih ada.
await ctx.close();
ctx = await buka();
[sw] = ctx.serviceWorkers();
sw ??= await ctx.waitForEvent("serviceworker");
const halaman = await ctx.newPage();
await halaman.goto(`chrome-extension://${id}/options.html`);
await halaman.waitForFunction(() => document.querySelector("#situs").value !== "");
assert.equal(await halaman.inputValue("#situs"), "example.com");
console.log("ok  daftar situs tetap ada setelah browser dibuka ulang");

await ctx.close();
console.log("SEMUA LULUS");
